using FluentValidation; using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Security; using JTradeERP.Domain.Security; using MediatR;
namespace JTradeERP.Application.Features.Security.Administration.AssignRoles;
public sealed record AssignRolesCommand(Guid UserId,IReadOnlyCollection<Guid> RoleIds):IRequest<AssignRolesResponse>;
public sealed record AssignRolesResponse(Guid UserId,IReadOnlyCollection<Guid> RoleIds);
public sealed class AssignRolesValidator:AbstractValidator<AssignRolesCommand>{public AssignRolesValidator(){RuleFor(x=>x.UserId).NotEmpty();RuleFor(x=>x.RoleIds).NotNull();}}
public sealed class AssignRolesHandler(IApplicationDbContext db,ICurrentUserService actor):IRequestHandler<AssignRolesCommand,AssignRolesResponse>{public async Task<AssignRolesResponse> Handle(AssignRolesCommand r,CancellationToken ct){if(!db.Users.Any(x=>x.Id==r.UserId))throw new NotFoundException("User was not found.");var ids=r.RoleIds.Distinct().ToArray();if(ids.Any(id=>!db.Roles.Any(x=>x.Id==id)))throw new NotFoundException("One or more roles were not found.");var old=db.UserRoles.Where(x=>x.UserId==r.UserId).Select(x=>x.RoleId).ToArray();foreach(var row in db.UserRoles.Where(x=>x.UserId==r.UserId&&!ids.Contains(x.RoleId)).ToArray())db.Remove(row);foreach(var id in ids.Except(old))db.Add(new UserRole(r.UserId,id));SecurityAuditWriter.Add(db,actor.UserId,"UserRolesAssigned","User",r.UserId.ToString(),string.Join(',',old),string.Join(',',ids));await db.SaveChangesAsync(ct);return new(r.UserId,ids);}}
public static class AssignRolesEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapPut("/users/{id:guid}/roles",async(Guid id,AssignRolesCommand c,ISender s,CancellationToken t)=>Results.Ok(await s.Send(c with{UserId=id},t))).RequirePermission("Admin.Users.Manage",Capability.Full);}
